/// Seals the header with the block hash.
/// Uses lazy sealing: SealedHeader::new_unhashed creates without hashing, SealedHeader::new with known hash.
#[derive(Debug, Clone, AsRef, Deref)]
pub struct SealedHeader<H = Header> {
    /// Block hash (lazily computed via OnceLock)
    hash: OnceLock<BlockHash>,
    /// Locked Header fields.
    header: H,
}
impl<H> SealedHeader<H> {
    pub fn new_unhashed(header: H) -> Self { Self { header, hash: Default::default() } }
    pub fn new(header: H, hash: BlockHash) -> Self { Self { header, hash: hash.into() } }
    pub fn into_header(self) -> H { self.header }
    pub fn unseal(self) -> H { self.header }
}
impl<H: Sealable> SealedHeader<H> {
    pub fn seal_slow(header: H) -> Self { let hash = header.hash_slow(); Self::new(header, hash) }
    pub fn hash_ref(&self) -> &BlockHash { self.hash.get_or_init(|| self.header.hash_slow()) }
    pub fn hash(&self) -> BlockHash { *self.hash_ref() }
}

