// PRIMARY: crates/consensus/common/src/validation.rs:validate_against_parent_eip1559_base_fee (lines 303-330)
pub fn validate_against_parent_eip1559_base_fee<ChainSpec: EthChainSpec + EthereumHardforks>(
    header: &ChainSpec::Header, parent: &ChainSpec::Header, chain_spec: &ChainSpec,
) -> Result<(), ConsensusError> {
    if chain_spec.is_london_active_at_block(header.number()) {
        let base_fee = header.base_fee_per_gas().ok_or(ConsensusError::BaseFeeMissing)?;
        let expected_base_fee = if chain_spec.ethereum_fork_activation(EthereumHardfork::London)
            .transitions_at_block(header.number())
        { alloy_eips::eip1559::INITIAL_BASE_FEE }
        else { chain_spec.next_block_base_fee(parent, header.timestamp()).ok_or(ConsensusError::BaseFeeMissing)? };
        if expected_base_fee != base_fee {
            return Err(ConsensusError::BaseFeeDiff(GotExpected { expected: expected_base_fee, got: base_fee }))
        }
    }
    Ok(())
}

// PRIMARY: crates/consensus/common/src/validation.rs:validate_4844_header_standalone (lines 234-259)
pub fn validate_4844_header_standalone<H: BlockHeader>(header: &H, blob_params: BlobParams) -> Result<(), ConsensusError> {
    let blob_gas_used = header.blob_gas_used().ok_or(ConsensusError::BlobGasUsedMissing)?;
    if header.parent_beacon_block_root().is_none() { return Err(ConsensusError::ParentBeaconBlockRootMissing) }
    if !blob_gas_used.is_multiple_of(DATA_GAS_PER_BLOB) {
        return Err(ConsensusError::BlobGasUsedNotMultipleOfBlobGasPerBlob { blob_gas_used, blob_gas_per_blob: DATA_GAS_PER_BLOB })
    }
    if blob_gas_used > blob_params.max_blob_gas_per_block() {
        return Err(ConsensusError::BlobGasUsedExceedsMaxBlobGasPerBlock { blob_gas_used, max_blob_gas_per_block: blob_params.max_blob_gas_per_block() })
    }
    Ok(())
}
// RELATED: validate_against_parent_4844 (lines 399-433)
pub fn validate_against_parent_4844<H: BlockHeader>(header: &H, parent: &H, blob_params: BlobParams) -> Result<(), ConsensusError> {
    let expected_excess_blob_gas = blob_params.next_block_excess_blob_gas_osaka(parent_excess_blob_gas, parent_blob_gas_used, parent_base_fee_per_gas);
    if expected_excess_blob_gas != excess_blob_gas { return Err(ConsensusError::ExcessBlobGasDiff { ... }) }
    Ok(())
}

