// PRIMARY: crates/ethereum/primitives/src/transaction.rs:Transaction (lines 46-113)
pub enum Transaction {
    /// Legacy transaction (type 0x0).
    Legacy(TxLegacy),
    /// EIP-2930 access list tx (type 0x1).
    Eip2930(TxEip2930),
    /// EIP-1559 fee market tx (type 0x2).
    Eip1559(TxEip1559),
    /// EIP-4844 blob tx (type 0x3).
    Eip4844(TxEip4844),
    /// EIP-7702 set-code tx (type 0x4).
    Eip7702(TxEip7702),
}
impl Transaction {
    fn tx_type(&self) -> TxType {
        match self {
            Self::Legacy(_) => TxType::Legacy,
            Self::Eip2930(_) => TxType::Eip2930,
            Self::Eip1559(_) => TxType::Eip1559,
            Self::Eip4844(_) => TxType::Eip4844,
            Self::Eip7702(_) => TxType::Eip7702,
        }
    }
}

