// CALLEE: crates/consensus/common/src/validation.rs:validate_shanghai_withdrawals (lines 58-71)
pub fn validate_shanghai_withdrawals<B: Block>(block: &SealedBlock<B>) -> Result<(), ConsensusError> {
    let withdrawals = block.body().withdrawals().ok_or(ConsensusError::BodyWithdrawalsMissing)?;
    let withdrawals_root = alloy_consensus::proofs::calculate_withdrawals_root(withdrawals);
    let header_withdrawals_root = block.withdrawals_root().ok_or(ConsensusError::WithdrawalsRootMissing)?;
    if withdrawals_root != *header_withdrawals_root {
        return Err(ConsensusError::BodyWithdrawalsRootDiff(...));
    }
    Ok(())
}

